export interface RefundBatchItem {
  /**
   * Refund destination address. Defaults to the payment's payer_address; required only for
   * Bitcoin/UTXO.
   */
  address?: string;
  /**
   * The amount to refund, in the payment coin. Without it the refund is what is still refundable:
   * the refundable amount less the refunds already made. The refundable amount is the most that all
   * refunds of this payment together can send (refund.exceeds_refundable), and it follows the
   * store's refund fee setting (getRefundFeeConfig). The payer's network surcharge is never
   * refunded. When the customer bears the Oblodai commission, it is the amount paid minus the
   * surcharge and the commission — what was credited to your balance for this payment. When you
   * bear it, it is the amount paid minus the surcharge: the commission is paid from your balance,
   * so the refunds debit more than the payment credited, and a balance too small for that fails
   * with payout.insufficient_funds. POST /v1/payment/refund/calculate shows these numbers.
   */
  amount?: string;
  /**
   * Fund the refund by converting balance: USDT → the payment currency only. Needed when the
   * payment coin has already been converted by auto-exchange.
   */
  from_currency?: string;
  /** Network. */
  network?: string;
  /** Your order reference of the payment. Either uuid or order_id is required. */
  order_id?: string;
  /**
   * An optional refund idempotency key: distinguishes two different refunds with the same (payment,
   * address, amount); a retry with the same value is deduplicated. This is not order_id.
   */
  reference: string;
  /** Payment id. Either uuid or order_id is required. */
  uuid?: string;
}

export interface RefundBatchRequest {
  /**
   * What to do when an item fails: continue (default) — process the rest; stop — stop processing
   * after the first error.
   */
  on_error?: OpenEnum<BatchOnError>;
  /**
   * An array of 1 to 5000 items — the same fields as in POST /v1/payment/refund; each item requires
   * reference (the idempotency key) and the payment's uuid or order_id.
   */
  refunds: RefundBatchItem[];
}

export interface RefundCalculation {
  /** Where the refund would go. */
  address: string;
  /**
   * true — address was omitted and the refund goes to the recorded payer_address (allowed only when
   * payer_address_is_refundable = true); false — the address you passed.
   */
  address_is_payer: boolean;
  /**
   * What this refund would send: the amount you passed, or by default the remaining refundable
   * amount.
   */
  amount: string;
  /** What the buyer paid in total, including the network surcharge. */
  amount_paid: string;
  /**
   * The Oblodai commission withheld from the refund: the payment's commission when
   * commission_bearer is customer, 0 when it is merchant (you then pay it from your balance).
   */
  commission: string;
  /**
   * Who bears the Oblodai commission on this refund — the store's refund fee setting
   * (getRefundFeeConfig): customer — it is deducted from the refund, and the refunds return at most
   * what the payment credited you; merchant — it is not deducted, and you pay it from your balance,
   * so the refunds debit more than the payment credited.
   */
  commission_bearer: OpenEnum<RefundCommissionBearer>;
  /**
   * What this payment credited to your balance; null — cannot be reconstructed (a legacy payment).
   */
  credited: string | null;
  /** The refund coin — the one the buyer paid with. */
  currency: string;
  /**
   * How much USDT the funding conversion would debit, at the current rate plus the conversion
   * spread; it re-prices at execution. Present only with from_currency.
   */
  from_amount?: string;
  /** The currency whose conversion would fund the refund (from_currency); present only then. */
  funded_by?: string;
  /** The network the refund would be sent on (canonical). */
  network: string;
  /** Your order_id of the payment; null if it has none. */
  order_id: string | null;
  /** USDT per 1 unit of currency used for from_amount. Present only with from_currency. */
  rate?: string;
  /**
   * The most that all refunds of this payment together may send; the surcharge is never refunded.
   * commission_bearer customer: amount_paid minus surcharge minus commission, never more than
   * credited. commission_bearer merchant: amount_paid minus surcharge (the surcharge counted per
   * deposit), more than credited by the commission you pay from your balance.
   */
  refundable: string;
  /** Already refunded (live and completed refunds; failed and cancelled ones do not count). */
  refunded: string;
  /** refundable minus refunded: what can still be refunded before this refund. */
  remaining: string;
  /**
   * The payer's network surcharge inside amount_paid: the cost of accepting the deposit, never
   * refunded from your balance.
   */
  surcharge: string;
  /** The payment id. */
  uuid: string;
}

